file.content:
  "description": "confirmation/evaluationを同一artifact digestへpinしstale PASSを拒否する"
},
"source_lineage": {
  "type": "object",
  "required": [
    "origin_kind",
    "source_plugin",
    "source_path",
    "source_version",
    "source_digest",
    "imported_at"
  ],
  "properties": {
    "origin_kind": {
      "type": "string",
      "enum": [
        "manual",
        "github",
        "system-spec-harness",
        "system-dev-planner",
        "generated"
      ]
    },
    "source_plugin": {
      "type": [
        "string",
        "null"
      ]
    },
    "source_path": {
      "type": [
        "string",
        "null"
      ],
      "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
    },
    "source_version": {
      "type": [
        "string",
        "null"
      ]
    },
    "source_digest": {
      "type": [
        "string",
        "null"
      ],
      "pattern": "^[a-f0-9]{64}$"
    },
    "imported_at": {
      "type": [
        "string",
        "null"
      ],
      "format": "date-time"
    }
  },
  "additionalProperties": false,
  "description": "引用・import元を追跡し、C19およびexternal plugin system-dev-planner由来のimportが外部正本を利用したことを検証する"
},
